def emi(principal, annual_rate_percent, months):
    annual_rate = annual_rate_percent / 100 / 12
    monthly_rate = annual_rate / (1 - (1 + annual_rate) ** (-months))
    return principal * monthly_rate / (1 - (1 + monthly_rate) ** (-months))

